// Junta o texto do modelo com os dados da pessoa e prepara o envio pela Meta.
var d = $json;

// Valores que entram no lugar de {{1}}, {{2}}... (a Meta não aceita quebra de linha nem campo vazio)
var valores = Array.isArray(d.valores) ? d.valores : [];
var limpos = valores.map(function (v) {
  return String(v == null ? '' : v).replace(/[\n\r\t]+/g, ' ').replace(/ {2,}/g, ' ').trim().slice(0, 1000);
});
var dadosOk = limpos.every(function (v) { return v.length > 0; });

// Troca {{n}} pelo valor correspondente
function preencher(texto, lista) {
  var partes = String(texto || '').split('{{');
  var saida = partes[0];
  for (var i = 1; i < partes.length; i++) {
    var fim = partes[i].indexOf('}}');
    if (fim === -1) { saida += '{{' + partes[i]; continue; }
    var n = parseInt(partes[i].slice(0, fim).trim(), 10);
    var v = (!isNaN(n) && lista[n - 1] !== undefined) ? lista[n - 1] : '';
    saida += v + partes[i].slice(fim + 2);
  }
  return saida;
}

var telefone = String(d.telefone || '').replace(/\D/g, '');
var corpo = preencher(d.texto, limpos);
var mensagemVisual = d.rodape ? corpo + '\n\n' + d.rodape : corpo;

var template = { name: d.meta_template_name, language: { code: d.idioma || 'pt_BR' } };
if (limpos.length > 0) {
  template.components = [{ type: 'body', parameters: limpos.map(function (v) { return { type: 'text', text: v }; }) }];
}

var podeWhatsapp = telefone.length > 0 && dadosOk;
var motivoSemWhatsapp = telefone.length === 0
  ? 'Pessoa sem telefone cadastrado.'
  : (dadosOk ? null : 'Faltou um dado da pessoa para preencher a mensagem.');

// Mensagem no formato que a memória da IA guarda (assim a IA sabe o que foi enviado)
var memoria = JSON.stringify({
  type: 'ai',
  data: { content: mensagemVisual, tool_calls: [], invalid_tool_calls: [], additional_kwargs: {}, response_metadata: {} }
});

return [{ json: Object.assign({}, d, {
  telefone: telefone,
  mensagem_visual: mensagemVisual,
  resultado_api: { messaging_product: 'whatsapp', to: telefone, type: 'template', template: template },
  redis_memory_message: memoria,
  pode_whatsapp: podeWhatsapp,
  motivo_sem_whatsapp: motivoSemWhatsapp
}) }];

