// O logo vai DENTRO do e-mail (anexo "inline"): Gmail e Outlook não mostram imagem SVG e muitos
// e-mails bloqueiam imagens que vêm de um endereço externo.
var esc = function (s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};

var LOGO_BASE64 = '';
var WHATSAPP_NUMERO = '558523980088';
var AZUL_BMS = '#021D44';
var LARANJA_BMS = '#FF7F00';
var COR_TEXTO = '#14233D';

var d = $json;
var subject = (d.assunto_email && String(d.assunto_email).trim()) ? d.assunto_email : 'Retomando nosso contato';

